Object.assign(SCENES, {
tr_adj: { title:'按实际进度', img:'s_office', who:'caizheng', topic:'t_adj',
  text:'年中预算调整方案是阮学文亲自送过来的。财政局长给市委送材料，一年没几回。\n他没急着走，站在书记桌子边上，把方案翻到第十一页，手指在一行字上停了停。\n书记那三件事的钱，又挪走了一块。旁边一栏写着：按实际进度安排。\n阮学文说：「这是政府常务会定的，我们只管算账。」说完他把方案合上，放在桌角，退出去了。\n书记看了一会儿门口。\n「进度慢，是因为钱没到。钱不到，进度怎么快？」\n方案下个月上常委会。',
  opts:[
    { t:'把挪走的那几笔一笔一笔划出来，夹张条子给书记', fx:{ trust:2 },
      res:'你划了三个钟头。条子夹进去的第二天，书记在第十一页那一栏旁边，画了一个问号。' },
    { t:'去统战部、宣传部各坐一坐，把那几笔的去向说一说', fx:{ heat:1, bmod:{ t_adj:{ tongzhan:5, xuanchuan:5 } } },
      res:'纪守望听完，说侨联那栋楼今年又没钱修了。方静仪没说话，把保温杯拧上，又拧开。' },
    { t:'去城管局问问，今年主城区的路灯怎么又换了', fx:{ heat:2, flag:'hid_t_adj' },
      res:'城管局的人把中标公告翻出来给你看。灯具公司的名字你没听过，法人那一栏的名字，你在市政府办的通讯录上见过一回，登记在景国梁家属那一页。' }
  ] },

tr_school: { title:'放学', img:'s_oldtown', who:null, topic:'t_school',
  text:'城关一小的校门口，放学铃响过十分钟，出来的孩子不到二十个。门口卖烤红薯的等了一会儿，推着车走了。\n同一个钟头，新城那边的实验小学，一间教室坐了六十三个人，最后一排的孩子贴着墙。\n教育局的布局调整方案送到市委，新城建两所，老城撤三所。撤的三所都在城关，城关的家长群已经传开了。\n书记在车里看着那个卖烤红薯的走远。\n「老城三所学校，一个年级凑不满一个班。新城的孩子，挤在一间教室里上课。」\n方案下个月上常委会。',
  opts:[
    { t:'去新城实验小学，在最后一排站一节课', fx:{ trust:1, bmod:{ t_school:{ depsec:5, mishuzhang:4 } } },
      res:'一节课四十分钟，你没找到地方放手。下课的时候，有个孩子问你是不是新来的老师。' },
    { t:'先去跟方静仪说一声，撤校名单里有二中分校', fx:{ side:{ xuanchuan:4 }, bmod:{ t_school:{ xuanchuan:5 } } },
      res:'方静仪愣了一下。「启明没跟我说过。」她把名单看了两遍，「谢谢你啊，小{SUR}。这个要是传出去，就不好办了。」' },
    { t:'去自然资源局，查那三块校址的控规', fx:{ heat:2, flag:'hid_t_school' },
      res:'三块地的控规前年就改了，从教育用地改成商住。批文上盖的是市政府的章。' }
  ] },

tr_env: { title:'反馈会', img:'s_changwei', who:'jiwei', topic:'t_env',
  text:'中央环保督察组的反馈会开了一个上午。组长念到港口的时候，念得很慢，两个排污口的坐标报了两遍。\n会后宋自强在走廊里等书记。他不寒暄，把反馈意见翻到最后一页：追责那一栏，要写人名。\n「哪天报？」\n「下个月上常委会。」书记说。\n回办公室的路上，书记把反馈意见递给你。\n「每一条后面写一个人名。写不上名字的，写我的。」',
  opts:[
    { t:'替书记把「责任人」那一栏拟出来，一条一个名字', fx:{ trust:1, bmod:{ t_env:{ depsec:5, tongzhan:4 } } },
      res:'你拟了两稿。第二稿里，你把几个名字往后挪了一格。书记看完只改了一处，把他自己的名字挪到了第一行。' },
    { t:'把反馈意见里点到的单位，先抄一份给宋自强', fx:{ side:{ jiwei:5 } },
      res:'宋自强接过去，从头看到尾。「几个人签的环评？」你说回去查。他点点头，把纸折了两折，放进上衣口袋。' },
    { t:'去生态环境局，把港口那两个口子的环评调出来', fx:{ heat:2, flag:'hid_t_env' },
      res:'档案袋很新。环评是去年补办的，比排污口投用晚了两年。补办手续最后一页，签字的是高振邦。' }
  ] },

tr_invest: { title:'签约仪式', img:'s_hotel', who:'gaoxin', topic:'t_invest',
  text:'投洽会的签约仪式在云州宾馆二楼，一上午签了十九个项目，签约额念出来，台下鼓了三回掌。\n吴敬之坐在第三排，一次也没鼓。散场的时候他跟你并排下楼。\n「去年签的，今年到了几个？」他没等你答，「你去问问招商局，问他们敢不敢把到位的数报上来。」\n晚上书记看了招商局的月报，把月报推到一边。\n「签了三百个亿，到位不到三十个亿。这个数，你信吗？」\n新的考核办法，下个月上常委会。',
  opts:[
    { t:'去高新区看两家已经投产的厂', fx:{ side:{ gaoxin:3 }, bmod:{ t_invest:{ tongzhan:5, depsec:4 } } },
      res:'两家厂的车间都在响。纪守望后来问你看了什么，你把厂名报了一遍，他记在本子上。' },
    { t:'请吴敬之把高新区三年的到位台账送一份过来', fx:{ trust:1, side:{ gaoxin:5 } },
      res:'台账第二天一早就到了，装订好的，每一页都盖了章。吴敬之在封面上写了一行：请周书记审阅。' },
    { t:'去市场监管局，查城关那笔八十个亿的签约方', fx:{ heat:2, flag:'hid_t_invest' },
      res:'注册资本五百万，成立十一个月。注册地址那一栏，写的是立民建设办公楼的门牌号。' }
  ] },

tr_petition: { title:'第一个号', img:'s_petition', who:null, topic:'t_petition',
  text:'信访局早上八点开门，七点半门口已经坐了一排人。坐第一个的是个老太太，手里一个塑料袋，里面是一份二十年前的拆迁协议，折痕都磨白了。\n马春来陪着书记从后门进去。他把积案台账递过来，薄薄一本，四十一件三年以上的，有十几件连包案领导那一栏都是空的。\n书记翻到空着的那几页，停了一会儿。\n「积了十年的案子，不是老百姓难缠，是我们没人管。」\n包案方案下个月上常委会。',
  opts:[
    { t:'把四十一件老案子逐件抄一遍，按年份排好', fx:{ trust:2, heat:-1 },
      res:'抄到半夜。最早那一件，比你参加工作还早六年。' },
    { t:'台账复印一份，送到纪委宋自强手上', fx:{ side:{ jiwei:5, zhengfa:-3 } },
      res:'宋自强收下了，没说谢谢。第二天韩树声在走廊上碰见你，问信访局的台账是不是少了一本。' },
    { t:'查查那几件拆迁老案是哪年、哪个区的', fx:{ heat:2, flag:'hid_t_petition' },
      res:'九件，都在城关，都是那几年的事。协议上的区政府公章旁边，有一个手签的名字：陈立群。' }
  ] },

tr_hospital: { title:'挂号', img:'s_hospital', who:null, topic:'t_hospital',
  text:'市一院门诊大厅，早上六点半，挂号的队排到了门外的台阶上。排在你前面的是个从梅岭来的老头，昨天晚上坐的夜班车。\n三家市属医院，隔着不到三站路，各有一台核磁，各有一个院长，各报各的采购。\n卫健委的合并方案送上来，三个院长合成一个。冷秋实在电话里说，三家都来找过他了。\n书记听你说完排队的事，点了根烟，没抽。\n「三个院长，三套设备，三回采购。病人还是挂不上号。」\n方案下个月上常委会。',
  opts:[
    { t:'把排队那天的事写成两页纸，送宣传部和组织部', fx:{ trust:1, bmod:{ t_hospital:{ xuanchuan:5, depsec:3 } } },
      res:'方静仪看完问，这个要不要内参。你说先不用。她把两页纸夹进了自己的本子。' },
    { t:'请冷秋实把三个院长的意见各写一页', fx:{ side:{ weijian:5 }, meet:['weijian'] },
      res:'三页纸，三个笔迹。有一页写了四行，另外两页都写满了。冷秋实在最后附了一句：以上意见，供参考。' },
    { t:'打听打听，市一院那台核磁是怎么买的', fx:{ heat:2, flag:'hid_t_hospital' },
      res:'设备科的人说，那台是去年进的，比省里同型号贵了四成。合同签的那年，卫健口是高振邦分管。' }
  ] },

tr_debt: { title:'到期表', img:'s_office', who:'caizheng', topic:'t_debt',
  text:'阮学文把城投公司的到期表摊在书记桌上。一张 A3 纸，从左到右，每个月一格，明年那一行红了一半。\n「明年到期十一个亿。」他说完这句就不说了。\n书记看了很久，拿笔在三个在建项目上各点了一下。三个都是市政府前几年上的。\n阮学文收表的时候，手在纸边上按了一下，把折角压平了。\n书记等他出了门。\n「借钱修的路，不能让下一任拿命去还。」\n化解方案下个月上常委会。',
  opts:[
    { t:'请阮学文把到期表按月重新排一张，每一笔写上用途', fx:{ trust:1, bmod:{ t_debt:{ zuzhi:4, depsec:4 } } },
      res:'新表第三天送来，多了一栏「用途」。有两格，阮学文写的是「待核」。' },
    { t:'去审计局，要一份去年城投的审计报告', req:function(){ return own('shenji') || P('qianwj').met; }, no:'审计局那边，你现在一个说得上话的人也没有',
      fx:{ grip:{ vice1:1 }, bmod:{ t_debt:{ jiwei:4 } } },
      res:'报告第四十页，两笔钱，去向一栏空着。你把那一页折了个角。' },
    { t:'问问城投这几任董事长都是谁', fx:{ heat:2, flag:'hid_t_debt' },
      res:'现任的那位，你见过。陈市长当常务副市长那几年，他是陈市长的秘书，拎包、开门、递稿子。' }
  ] },

tr_oldhouse: { title:'两份名单', img:'s_oldtown', who:'zhujian', topic:'t_oldhouse',
  text:'老旧小区改造的名单，城关区报了一份，住建局报了一份。卢志高把两份并排钉在一起送过来，对得上的不到一半。\n城关那份排第一的，是区委家属院。住建局那份排第一的，是一栋六层的老楼，楼道里的水管去年冬天冻裂过两回。\n卢志高说：「两份我都照实报了。」说完他看你，等你接话。\n书记看了两份名单的头一行。\n「先改哪个，看谁家水管漏，不看谁家住着干部。」\n计划下个月上常委会。',
  opts:[
    { t:'去住建局名单上那栋六层老楼看一看', fx:{ trust:1, bmod:{ t_oldhouse:{ depsec:5, tongzhan:5 } } },
      res:'楼道里的水管外面缠着一层旧棉被。一个老太太扶着栏杆往上走，走两层歇一回。' },
    { t:'请卢志高把两份名单合成一份，按漏水报修的次数排', fx:{ side:{ zhujian:4 } },
      res:'卢志高答应得很快。合出来那份，区委家属院排到了第三十七。' },
    { t:'查查城关名单前十都是些什么小区', fx:{ heat:2, flag:'hid_t_oldhouse', grip:{ chengguan:1 } },
      res:'前十里有四个是区直单位的家属院。排第一的那个，三楼住着一位老太太，是邵国栋的岳母。' }
  ] },

tr_cadre: { title:'第七稿', img:'s_office', who:'zuzhi', topic:'t_cadre',
  text:'佟建民把容错纠错机制的意见送来，是第七稿。他先喝了口茶。\n「这个文件嘛，按程序，要先征求纪委的意见。宋书记对『可以免责』这四个字，有看法。」\n他把稿子推过来，第三条那四个字底下，画了一道铅笔线，不知道是谁画的。\n旧改指挥部报上来一个副指挥，签错了一笔拆迁款，纪委那边已经在问了。\n书记把第三条看了两遍。\n「干事的人怕出错，不干事的人不会错。这样下去，谁还干事？」\n意见下个月上常委会。',
  opts:[
    { t:'把前六稿也要来，对一对哪句话改了几回', fx:{ trust:1, side:{ zuzhi:3 } },
      res:'「可以免责」这四个字，前六稿都在。第七稿里，有人在底下画了线。佟建民说，线是他自己画的。' },
    { t:'去纪委，听宋自强对「可以」两个字怎么说', fx:{ side:{ jiwei:2 }, bmod:{ t_cadre:{ jiwei:6 } } },
      res:'宋自强只问了一句：「谁来认定？」你说组织部。他想了一会儿，说改成「可以从轻」，他没意见。' },
    { t:'问问市政府办那边，对这份文件是怎么议论的', fx:{ heat:1, flag:'hid_t_cadre' },
      res:'韦青说，陈市长在政府党组会上讲过一句：「容错这个东西，谁来认定，就是谁说了算。」讲完没人接话。' }
  ] },

tr_safety: { title:'电话', img:'s_county', who:null, topic:'t_safety',
  text:'安全生产整治方案的征求意见稿发下去第三天，市委总机接的区县电话一下子多了起来，都是找常委的。\n方案里有一条：发生较大事故的，年度考核一票否决。\n区县书记在常委会上没有票，可每个人都知道该给谁打电话。\n白沙的程一鸣打到了你这儿。他说得很客气，说一票否决他双手赞成，就是白沙的采石场多，怕一年白干。\n书记听你转述完，把征求意见稿翻到那一条。\n「死一个人，一个县一年白干。不这么写，没人当回事。」\n方案下个月上常委会。',
  opts:[
    { t:'跟应急局去一个采石场，看一回夜班', fx:{ trust:1, bmod:{ t_safety:{ depsec:4, tongzhan:4 } } },
      res:'炸药库的门没锁。带班的说，平时都锁，今天钥匙在老板那儿。' },
    { t:'替书记把三个县委书记的电话都接了，一个一个记下来', fx:{ side:{ baisha:3, meiling:3 } },
      res:'三个人说的话差不多，都说双手赞成。贺兰生多说了一句：梅岭没有矿，他就是打来问问。' },
    { t:'问问总机，这几天谁给谁打了电话', fx:{ heat:2, flag:'hid_t_safety' },
      res:'总机的小姑娘翻了一下记录。头一个打进来的是青川，马汉江，要的是市长办公室，通话四十分钟。' }
  ] },

tr_org: { title:'三十个编制', img:'s_archive', who:'mishuzhang', topic:'t_org',
  text:'编制调整方案要撤四个事业单位，腾出三十个编制。撤的单位里，一个是市委办的档案史志室，一个是市政府办的经济研究中心。\n邱仲华来送方案，在门口站着说了几句。\n「史志室那两个老同志，我干秘书那会儿就在了。小{SUR}，你还年轻，写县志的人，以后会越来越少。」\n他把方案放下就走了。\n纪委要人，要了一年。信访局窗口不够，排队的人排到大门外。\n书记翻到撤并名单。\n「编制腾出来，给纪委和信访。一个萝卜一个坑，坑不腾，萝卜往哪儿栽？」\n方案下个月上常委会。',
  opts:[
    { t:'去档案史志室坐一个下午', fx:{ side:{ mishuzhang:4 } },
      res:'两个老同志在誊一份民国年间的县志。临走的时候，其中一个送了你一本，扉页上写着：邱仲华同志指正。那是二十年前的字。' },
    { t:'把腾出来的编制给谁，先透给宋自强', fx:{ side:{ jiwei:2 }, bmod:{ t_org:{ jiwei:5 } } },
      res:'宋自强问：「几个？」你说三个。他点了一下头，那天是他头一回送你到电梯口。' },
    { t:'去市经济研究中心看看账', fx:{ heat:2, flag:'hid_t_org' },
      res:'会计是个快退休的大姐。她翻出一笔课题费，一百四十万，还没花完。委托方那一栏写着：立民建设。' }
  ] },

tr_culture: { title:'横幅', img:'s_county', who:'meiling', topic:'t_culture',
  text:'贺兰生从梅岭来，带了两箱茶，放在门卫室没往上拿。\n他在书记办公室坐了二十分钟，讲梅岭的古镇、梅岭的茶、梅岭的年轻人都去了外地。讲到文旅节，他说宣传部去年报过一回，市政府没批。\n「今年的横幅，县里已经印好了。」\n他走的时候，把一沓照片留在了桌上。古镇的石板路，一个人也没有。\n书记把照片一张一张翻过去。\n「梅岭穷，穷在没人知道。花这笔钱买个名字，值不值，三年以后看。」\n方案下个月上常委会。',
  opts:[
    { t:'陪贺兰生回一趟梅岭，在古镇上走一走', fx:{ side:{ meiling:5 }, bmod:{ t_culture:{ tongzhan:4 } } },
      res:'石板路走到头是一座祠堂，门锁着。贺兰生掏出钥匙开了门，说这钥匙他一直揣在身上。' },
    { t:'替方静仪把那位明星的档期先问一问', fx:{ side:{ xuanchuan:5 } },
      res:'经纪公司回话说，九月有空，价钱能谈。方静仪听完，把保温杯放下了。「这个要是成了，得上一回省台。」' },
    { t:'问问市政府那边明年的马拉松是哪家公司承办', fx:{ heat:2, flag:'hid_t_culture' },
      res:'公司去年才注册。法人的籍贯那一栏，跟市长秘书苏晓东是同一个村。' }
  ] },

tr_land: { title:'一张图', img:'s_city', who:null, topic:'t_land',
  text:'今年的土地出让计划，高新区报了十二宗，城关报了九宗，盘子只有十五宗。\n自然资源局的孟广仁来汇报，带了两份名单，没带图。书记问地块在哪儿，他说回去标。\n高新区那十二宗，有一半是东边那两千亩，吴敬之要扩区，等了两年。\n城关那九宗，孟广仁说了一句「都在老城边上」，就没往下说。\n书记拿笔在桌上的空白纸上画了一个圈，又画了一个。\n「地是云州最后一点家底。卖给谁，要看二十年以后。」\n计划下个月上常委会。',
  opts:[
    { t:'请孟广仁把二十一宗地标在一张图上送来', fx:{ trust:1, bmod:{ t_land:{ depsec:5 } } },
      res:'图第二天到了。书记看了很久，罗明川来汇报工作的时候，他把图推过去让罗明川也看了看。' },
    { t:'去高新区东边那两千亩地上走一走', fx:{ side:{ gaoxin:5 } },
      res:'地里种着玉米，田埂边上插着一排新木桩。吴敬之的司机说，桩子是吴书记自己带人去插的。' },
    { t:'查查城关那九宗地挨着什么', fx:{ heat:2, flag:'hid_t_land' },
      res:'有三宗挨着老货场。老货场那块地，前些日子刚过户，新主人是立民建设。' }
  ] },

tr_pension: { title:'活动室', img:'s_county', who:'gangkou', topic:'t_pension',
  text:'港口三家国企，四千多个退休职工，按方案要移交给社区。崔延平来汇报，说老职工的情绪很大。\n「他们手里有厂里签的字，说好管到底的。」\n他说完看了看书记，又补了一句：「当然，市委定了，我们坚决执行。」\n那天下午，港口机械厂的老职工活动室里，二十几个老头围着一张告示看。有人说，厂子没了，管他们的人也要没了。\n书记听你说完，看了一会儿窗外。\n「厂子要改，老人不能跟着厂子一起沉。移交社区，钱跟着人走，比现在强。」\n方案下个月上常委会。',
  opts:[
    { t:'去港口机械厂的活动室，跟老职工下一盘棋', fx:{ trust:1, bmod:{ t_pension:{ xuanchuan:4, tongzhan:4 } } },
      res:'你输了。赢你的老头说，他在厂里干了三十一年，厂里的体检单他一张也没见过。' },
    { t:'请国资委尹立本算一笔账：移交和不移交，各花多少', fx:{ meet:['guozi'], bmod:{ t_pension:{ depsec:5 } } },
      res:'尹立本算了两天。算完他打电话来，只报了一个差数，报完问你：「这个数，要不要写进材料？」' },
    { t:'问问退休管理费是从哪个口子走的', fx:{ heat:2, flag:'hid_t_pension' },
      res:'走的是港口区一家服务公司。公司不大，经理姓崔，是崔延平的弟弟。' }
  ] },

tr_rule: { title:'半个钟头', img:'s_changwei', who:'mishuzhang', topic:'t_rule',
  text:'上一次常委会开到一半，市政府办的人推门进来，递了一份材料，临时加了个议题。材料印出来还是热的，常委们翻了三页，举了手。\n散会以后，书记在会议室多坐了一会儿。\n「会上临时塞进来的议题，没人看过材料，举手就是瞎举。」\n议事规则的修订稿是邱仲华那边起草的，加了一条：议题须提前三天送达。\n邱仲华把修订稿交给你，笑了笑。\n「小{SUR}，这一条是冲着谁来的，会上每个人都清楚。你还年轻，这种稿子，改字不改意思。」\n修订稿下个月上常委会。',
  opts:[
    { t:'把过去一年临时加的议题都翻出来，列个单子', fx:{ trust:1, heat:1, flag:'hid_t_rule' },
      res:'七个。六个是市政府那边的，有五个是会前半个钟头才送到的。你把单子夹进修订稿，没写一个字的说明。' },
    { t:'找罗明川，把修订稿先请他过目', fx:{ side:{ depsec:2 }, bmod:{ t_rule:{ depsec:6 } } },
      res:'罗明川看完，说：「两位领导的意思我都理解。」隔了一会儿又说，「提前三天，是应该的。」' },
    { t:'请邱仲华在秘书长碰头会上先吹个风', fx:{ bmod:{ t_rule:{ mishuzhang:5, tongzhan:3 } } },
      res:'邱仲华答应了。碰头会上他讲了十分钟，讲他当秘书那会儿，常委会的材料要提前一个礼拜送。' }
  ] }
});

